662	
663	    fn publish(
664	        &self,
665	        target: SignalProcessId,
666	        event: SignalEvent,
667	        completion: Option<&reverie::ChildExitCompletion>,
668	        independent_carriers: bool,
669	    ) -> ProcessPublication {
670	        use ProcessPublication::Rejected;
671	        use PublicationRejection::*;
672	        let Some(registry) = self.0.upgrade() else {
673	            return Rejected(Closed);
674	        };
675	        // A committed result is a stable acknowledgement, not permission to
676	        // repeat the effect. Consult it before liveness validation so an exact
677	        // duplicate remains idempotent after the child executor retires.
678	        if let Some(completion) = completion
679	            && let Some(record) = registry
680	                .child_publications
681	                .lock()
682	                .unwrap_or_else(|p| p.into_inner())
683	                .get(&(completion.child.tgid.as_raw(), completion.child.generation))
684	                .cloned()
685	        {
686	            return if record.completion() == *completion {
687	                record.replay()
688	            } else {
689	                Rejected(InvalidCompletion)
690	            };
691	        }
692	        let Some(binding) = registry.lookup(target) else {
693	            return Rejected(StaleProcess);
694	        };
695	        let image = binding
696	            .image
697	            .lock()
698	            .unwrap_or_else(|p| p.into_inner())
699	            .clone();
700	        let (Some(transaction), Some(lifecycle), Some(signals)) = (
701	            binding.transaction.upgrade(),
702	            binding.lifecycle.upgrade(),
703	            image.signals.upgrade(),
704	        ) else {
705	            return Rejected(StaleProcess);
706	        };
707	        // The active path neither acquires nor pins an ordinary file table:
708	        // even dropping its final Arc could close an unrelated blocking socket
709	        // while the Tool holds its scheduler mutex. Only the inactive private
710	        // endpoint retains its historical table preflight and corruption checks.
711	        let files_owner = if independent_carriers {
712	            None
713	        } else {
714	            let Some(files) = image.files.upgrade() else {
715	                return Rejected(StaleProcess);
716	            };
717	            Some(files)
718	        };
719	        let files = match files_owner.as_ref() {
720	            Some(files) => match files.lock() {
721	                Ok(files) => Some(files),
722	                Err(_) => return Rejected(Backend(Errno::EIO)),
723	            },
724	            None => None,
725	        };
726	        let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
727	        if binding
728	            .image
729	            .lock()
730	            .unwrap_or_else(|p| p.into_inner())
731	            .revision
732	            != image.revision
733	        {
734	            return Rejected(ChangedImage);
735	        }
736	        let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
737	        if binding.identity != target
738	            || !lifecycle.contains_process(target.tgid.as_raw(), target.generation)
739	        {
740	            return Rejected(StaleProcess);
741	        }
742	        let child_snapshot = match completion {
743	            Some(completion) => match registry.process_family_exit(completion.child) {
744	                Some(ProcessFamilyExit::Child(snapshot)) if snapshot.completion == *completion => {
745	                    Some(snapshot)
746	                }
747	                _ => return Rejected(InvalidCompletion),
748	            },
749	            None => None,
750	        };
751	        if let Some(completion) = completion {
752	            let Some(child) = registry.lookup(completion.child) else {
753	                return Rejected(InvalidCompletion);
754	            };
755	            if child.parent != Some(target)
756	                || lifecycle.process_exit_status(
757	                    completion.child.tgid.as_raw(),
758	                    completion.child.generation,
759	                ) != Some(completion.status)
760	            {
761	                return Rejected(InvalidCompletion);
762	            }
763	        }
764	        // Serialize the run-local terminal latch through the entire commit.
765	        // This also prevents a different process from publishing after the
766	        // first failed readiness transaction. No Tool call can occur here.
767	        let mut failure = registry.failure.lock().unwrap_or_else(|p| p.into_inner());
768	        if failure.is_some() {
769	            return Rejected(Terminal);
770	        }
771	        // Keep this guard through the complete mutation and readiness phase.
772	        // A concurrent duplicate cannot pass the check before the first
773	        // operation records its irreversible commit.
774	        let mut child_publications = completion.map(|_| {
775	            registry
776	                .child_publications
777	                .lock()
778	                .unwrap_or_else(|p| p.into_inner())
779	        });
780	        if let (Some(completion), Some(publications)) = (completion, child_publications.as_ref())
781	            && let Some(previous) =
782	                publications.get(&(completion.child.tgid.as_raw(), completion.child.generation))
783	        {
784	            return if previous.completion() == *completion {
785	                previous.replay()
786	            } else {
787	                Rejected(InvalidCompletion)
788	            };
789	        }
790	        let mut process = signals.lock().unwrap_or_else(|p| p.into_inner());
791	        let signal = event.signal();
792	        let action = process
793	            .dispositions
794	            .get(&signal)
795	            .copied()
796	            .unwrap_or_default();
797	        let disposition = child_snapshot.map_or_else(
798	            || {
799	                if action.is_ignored() {
800	                    PublicationDisposition::Ignored
801	                } else if action.handler == libc::SIG_DFL as u64 {
802	                    PublicationDisposition::Default
803	                } else {
804	                    PublicationDisposition::Caught
805	                }
806	            },
807	            |snapshot| snapshot.disposition,
808	        );
809	        let pending_generation = child_snapshot.map_or_else(
810	            || process.pending_generation(signal),
811	            |snapshot| snapshot.pending_generation,
812	        );
813	        let mut receipt = PublicationReceipt {
814	            process: target,
815	            image: image.revision,
816	            signal,
817	            pending_generation,
818	            change: PendingChange::Suppressed,
819	            disposition,
820	            child_completion: completion.copied(),
821	        };
822	        if signal == libc::SIGCHLD && disposition == PublicationDisposition::Ignored {
823	            if let (Some(completion), Some(publications)) =
824	                (completion, child_publications.as_mut())
825	            {
826	                let previous = publications.insert(
827	                    (completion.child.tgid.as_raw(), completion.child.generation),
828	                    ChildPublicationRecord::Committed(receipt.clone()),
829	                );
830	                debug_assert!(previous.is_none());
831	            }
832	            return ProcessPublication::Committed(receipt);
833	        }
834	        if let Some(snapshot) = child_snapshot
835	            && process.pending_generation(signal) != snapshot.pending_generation
836	        {
837	            receipt.change = PendingChange::Discarded;
838	            if let (Some(completion), Some(publications)) =
839	                (completion, child_publications.as_mut())
840	            {
841	                let previous = publications.insert(
842	                    (completion.child.tgid.as_raw(), completion.child.generation),
843	                    ChildPublicationRecord::Committed(receipt.clone()),
844	                );
845	                debug_assert!(previous.is_none());
846	            }
847	            return ProcessPublication::Committed(receipt);
848	        }
849	        let matching = process
850	            .signalfd_masks
851	            .iter()
852	            .filter_map(|(&fd, mask)| mask.contains(signal).then_some(fd))
853	            .collect::<Vec<_>>();
854	        let carriers = if independent_carriers {
855	            let Some(carriers) = matching
856	                .iter()
857	                .map(|fd| process.signalfd_carriers.get(fd).cloned())
858	                .collect::<Option<Vec<_>>>()
859	            else {
860	                return Rejected(Backend(Errno::EBADF));
861	            };
862	            carriers
863	        } else {
864	            if matching.iter().any(|fd| {
865	                !files
866	                    .as_ref()
867	                    .expect("private endpoint owns table")
868	                    .files
869	                    .contains_key(fd)
870	            }) {
871	                return Rejected(Backend(Errno::EBADF));
872	            }
873	            Vec::new()
874	        };
875	        receipt.change = match process
876	            .shared_pending
877	            .enqueue(event, receipt.pending_generation)
878	        {
879	            Ok(true) => PendingChange::Queued,
880	            Ok(false) => PendingChange::Coalesced,
881	            Err(errno) => return Rejected(Backend(errno)),
882	        };
883	        // Release queue/lifecycle locks, retaining descriptor+transaction
884	        // ownership across only bounded, nonblocking eventfd readiness I/O.
885	        drop(process);
886	        drop(lifecycle);
887	        for (index, fd) in matching.into_iter().enumerate() {
888	            let file = if independent_carriers {
889	                carriers[index].file()
890	            } else {
891	                &files.as_ref().expect("private endpoint owns table").files[&fd]
892	            };
893	            if let Err(raw) = set_signalfd_ready(file, true) {
894	                let committed = PublicationFailure {
895	                    receipt,
896	                    errno: Errno::new(i32::try_from(-raw).unwrap_or(libc::EIO)),
897	                };
898	                if let (Some(completion), Some(publications)) =
899	                    (completion, child_publications.as_mut())
900	                {
901	                    let previous = publications.insert(
902	                        (completion.child.tgid.as_raw(), completion.child.generation),
903	                        ChildPublicationRecord::Failed(committed.clone()),
904	                    );
905	                    debug_assert!(previous.is_none());
906	                }
907	                *failure = Some(committed.clone());
908	                return ProcessPublication::FailedAfterCommit(committed);
909	            }
910	        }
911	        if let (Some(completion), Some(publications)) = (completion, child_publications.as_mut()) {
912	            let previous = publications.insert(
913	                (completion.child.tgid.as_raw(), completion.child.generation),
914	                ChildPublicationRecord::Committed(receipt.clone()),
915	            );
916	            debug_assert!(previous.is_none());
917	        }
918	        ProcessPublication::Committed(receipt)
919	    }
920	}
