922	fn child_exit_signal_event(
923	    completion: reverie::ChildExitCompletion,
924	) -> Result<SignalEvent, PublicationRejection> {
925	    if completion.user_ticks < 0 || completion.system_ticks < 0 {
926	        return Err(PublicationRejection::InvalidCompletion);
927	    }
928	    let (code, status) = match completion.status {
