1194	        let binding = registry.lookup(permit.task.process).ok_or(Errno::ESRCH)?;
1195	        let transaction = binding.transaction.upgrade().ok_or(Errno::ESRCH)?;
1196	        let lifecycle = binding.lifecycle.upgrade().ok_or(Errno::ESRCH)?;
1197	        let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
1198	        let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
