    state: &LoadedStaticElf,
    tgid: Option<libc::pid_t>,
    target: libc::pid_t,
    signal: libc::c_int,
) -> SyscallAction {
    if target <= 0 || tgid.is_some_and(|tgid| tgid <= 0) {
        return continue_with(negative_errno(libc::EINVAL));
    }
    {
        let lifecycle = state
            .task_lifecycle
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
