7	#[derive(Clone, Debug)]
8	enum Observation {
9	    Start(i32),
10	    ContextRefusal(i32, &'static str),
11	    Published(i32, SignalEvent, ChildExitSignalOutcome),
12	    Signal(i32, SignalEvent),
13	    ThreadExit(i32, ExitStatus),
14	    ProcessExit(i32, ExitStatus),
15	}
16	static OBSERVATIONS: Mutex<Vec<Observation>> = Mutex::new(Vec::new());
17	
18	fn observe(value: Observation) {
19	    OBSERVATIONS.lock().unwrap().push(value);
20	}
21	
22	fn event(pid: Pid, child: i32, uid: u32) -> SignalEvent {
23	    let mut info = [0; reverie::SIGNAL_INFO_SIZE];
24	    info[0..4].copy_from_slice(&libc::SIGCHLD.to_ne_bytes());
25	    info[8..12].copy_from_slice(&libc::CLD_EXITED.to_ne_bytes());
26	    info[16..20].copy_from_slice(&child.to_ne_bytes());
27	    info[20..24].copy_from_slice(&uid.to_ne_bytes());
28	    info[24..28].copy_from_slice(&37_i32.to_ne_bytes());
29	    info[32..40].copy_from_slice(&11_i64.to_ne_bytes());
30	    info[40..48].copy_from_slice(&13_i64.to_ne_bytes());
31	    info[127] = 0xa5;
32	    SignalEvent::new(libc::SIGCHLD, info, SignalTarget::Process { pid }).unwrap()
33	}
