35	#[derive(Default)]
36	struct ChildExitLog;
37	#[reverie::global_tool]
38	impl GlobalTool for ChildExitLog {
39	    type Request = ();
40	    type Response = ();
41	    type Config = u8;
42	    async fn receive_rpc(&self, _: Pid, _: ()) {}
43	}
