45	#[derive(Default)]
46	struct ChildExitTool {
47	    mode: u8,
48	    selected: Mutex<Option<SignalEvent>>,
49	}
50	impl ChildExitTool {
51	    async fn refused_context<G: Guest<Self>>(&self, guest: &mut G, context: &'static str) {
52	        let event = event(guest.pid(), 41, 0);
53	        assert_eq!(
54	            guest.queue_child_exit_signal(event).await,
55	            ChildExitSignalOutcome::RejectedBeforeCommit {
56	                kind: ChildExitSignalErrorKind::Unsupported,
57	                errno: Errno::ENOSYS,
58	            },
59	            "{context}"
60	        );
61	        observe(Observation::ContextRefusal(guest.tid().as_raw(), context));
62	    }
63	
64	    async fn publish<G: Guest<Self>>(&self, guest: &mut G) {
65	        let selected = self
66	            .selected
67	            .lock()
68	            .unwrap()
69	            .expect("selected actual child");
70	        self.publish_event(guest, selected, false).await;
71	    }
72	
73	    async fn publish_event<G: Guest<Self>>(
74	        &self,
75	        guest: &mut G,
76	        selected: SignalEvent,
77	        expected_coalesced: bool,
78	    ) {
79	        let outcome = guest.queue_child_exit_signal(selected).await;
80	        observe(Observation::Published(
81	            guest.tid().as_raw(),
82	            selected,
83	            outcome,
84	        ));
85	        let disposition = match self.mode {
86	            3 | 4 => ChildExitSignalDisposition::Ignored,
87	            2 | 7 | 13 => ChildExitSignalDisposition::PendingBlocked,
88	            _ => ChildExitSignalDisposition::PendingEligible,
89	        };
90	        let ChildExitSignalOutcome::Accepted {
91	            disposition: actual,
92	            coalesced,
93	            ..
94	        } = outcome
95	        else {
96	            panic!("live child-exit publication failed: {outcome:?}");
97	        };
98	        assert_eq!(actual, disposition);
99	        assert_eq!(coalesced, expected_coalesced);
100	    }
101	}
102	
103	#[reverie::tool]
104	impl Tool for ChildExitTool {
105	    type GlobalState = ChildExitLog;
106	    type ThreadState = bool;
107	
108	    fn new(_: Pid, mode: &u8) -> Self {
109	        Self {
110	            mode: *mode,
111	            ..Self::default()
112	        }
113	    }
114	
115	    async fn handle_thread_start<G: Guest<Self>>(
116	        &self,
117	        guest: &mut G,
118	    ) -> Result<(), reverie::Error> {
119	        assert!(!guest.thread_state());
120	        *guest.thread_state_mut() = true;
121	        observe(Observation::Start(guest.tid().as_raw()));
122	        self.refused_context(guest, "thread start").await;
123	        Ok(())
124	    }
125	
126	    async fn handle_post_exec<G: Guest<Self>>(&self, guest: &mut G) -> Result<(), Errno> {
127	        self.refused_context(guest, "post exec").await;
128	        Ok(())
129	    }
130	
131	    async fn handle_syscall_event<G: Guest<Self>>(
132	        &self,
133	        guest: &mut G,
134	        syscall: Syscall,
135	    ) -> Result<i64, reverie::Error> {
136	        assert!(*guest.thread_state());
137	        if matches!(syscall, Syscall::Execve(_)) {
138	            self.refused_context(guest, "initial exec").await;
139	        }
140	        let (_, args) = syscall.into_parts();
141	        if syscall.number() == Sysno::getpid && args.arg0 == 0x63686c64 {
142	            assert_eq!(args.arg1 as u8, self.mode);
143	            let child = args.arg2 as i32;
144	            let observations = OBSERVATIONS.lock().unwrap().clone();
145	            assert!(
146	                observations.iter().any(|value| matches!(
147	                    value,
148	                    Observation::ThreadExit(tid, ExitStatus::Exited(37)) if *tid == child
149	                )),
150	                "actual child's consuming exit must precede this waited-for publication"
151	            );
152	            *self.selected.lock().unwrap() = Some(event(guest.pid(), child, args.arg3 as u32));
153	            if self.mode != 10 && self.mode != 11 {
154	                self.publish(guest).await;
155	            }
156	            if self.mode == 13 {
157	                let second = args.arg4 as i32;
158	                assert!(
159	                    observations.iter().any(|value| matches!(value,
160	                        Observation::ThreadExit(tid, ExitStatus::Exited(43)) if *tid == second
161	                    )),
162	                    "second child's exact status must precede publication"
163	                );
164	                let mut info = event(guest.pid(), second, args.arg3 as u32).siginfo();
165	                info[24..28].copy_from_slice(&43_i32.to_ne_bytes());
166	                let event = SignalEvent::new(
167	                    libc::SIGCHLD,
168	                    info,
169	                    SignalTarget::Process { pid: guest.pid() },
170	                )?;
171	                self.publish_event(guest, event, true).await;
172	            }
173	            return Ok(i64::from(guest.pid().as_raw()));
174	        }
175	        guest.tail_inject(syscall).await
176	    }
177	
178	    async fn handle_structured_signal_event<G: Guest<Self>>(
179	        &self,
180	        guest: &mut G,
181	        signal: SignalEvent,
182	    ) -> Result<Option<SignalEvent>, Errno> {
183	        observe(Observation::Signal(guest.tid().as_raw(), signal));
184	        if signal.signal() == libc::SIGUSR1 && self.mode == 10
185	            || signal.signal() == libc::SIGSEGV && self.mode == 11
186	        {
187	            self.publish(guest).await;
188	            return Ok(Some(signal));
189	        }
190	        assert_eq!(signal.signal(), libc::SIGCHLD);
191	        assert_eq!(signal, self.selected.lock().unwrap().unwrap());
192	        if self.mode == 8 {
193	            return Ok(None);
194	        }
195	        if self.mode == 9 || self.mode == 12 {
196	            let mut info = signal.siginfo();
197	            let status: i32 = if self.mode == 9 { 43 } else { 256 };
198	            info[24..28].copy_from_slice(&status.to_ne_bytes());
199	            return Ok(Some(SignalEvent::new(
200	                libc::SIGCHLD,
201	                info,
202	                signal.target(),
203	            )?));
204	        }
205	        Ok(Some(signal))
206	    }
207	
208	    async fn on_exit_thread<G: GlobalRPC<Self::GlobalState>>(
209	        &self,
210	        tid: Pid,
211	        _: &G,
212	        state: bool,
213	        status: ExitStatus,
214	    ) -> Result<(), reverie::Error> {
215	        assert!(state);
216	        observe(Observation::ThreadExit(tid.as_raw(), status));
217	        Ok(())
218	    }
219	
220	    async fn on_exit_process<G: GlobalRPC<Self::GlobalState>>(
221	        self,
222	        pid: Pid,
223	        _: &G,
224	        status: ExitStatus,
225	    ) -> Result<(), reverie::Error> {
226	        observe(Observation::ProcessExit(pid.as_raw(), status));
227	        Ok(())
228	    }
229	}
